vec2 lat_four = lat_three * vec2(-1, 1.0 );
vec2 vrt_four = vrt_three * vec2(-1, 1.0 );
vec2 non_five = non_four.yx;
vec2 lat_five = lat_four.yx;
vec2 vrt_five = vrt_four.yx;
vec2 non_six = non_five * vec2(-1, 1.0 );
vec2 lat_six = lat_five * vec2(-1, 1.0 );
vec2 vrt_six = vrt_five * vec2(-1, 1.0 );
vec2 non_seven = non_six.yx;
vec2 lat_seven = lat_six.yx;
